def transform(grid):
    """task-d4079843: streams flow up and right from sources"""
    H, W = len(grid), len(grid[0])
    result = [[0]*W for _ in range(H)]

    # Find boundaries (rows with 1)
    has_boundary = set(r for r in range(H) if 1 in grid[r])

    # Find sources (3)
    sources = set((r, c) for r in range(H) for c in range(W) if grid[r][c] == 3)

    # Initialize with boundary value
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                result[r][c] = 1

    # Mark sources as 4
    for r, c in sources:
        result[r][c] = 4

    # Extend vertical streams UP through boundary rows
    for sr, sc in sources:
        for r in range(sr - 1, -1, -1):
            if r in has_boundary:
                if result[r][sc] not in (1, 4):
                    result[r][sc] = 3

    # For rows with boundaries, fill horizontal from col 1
    for r in has_boundary:
        row_has_sources = any((r, c) in sources for c in range(W))
        for c in range(1, W):
            if result[r][c] not in (1, 4):
                if row_has_sources:
                    first_source = min(c for c in range(W) if (r, c) in sources)
                    if c <= first_source:
                        continue  # Don't overwrite 4 or already filled
                result[r][c] = 3

    return result

